mapper.select:
SELECT ba.album_no, ba.baby_no, ba.photo_file_name, ba.taken_date, ba.latitude, ba.longitude, ba.reg_time FROM tbl_baby_album ba JOIN tbl_baby_info bi ON ba.baby_no = bi.baby_no WHERE ba.baby_no = #{babyNo} AND bi.email = #{email}
ORDER BY ba.taken_date ASC, ba.album_no ASC
ORDER BY ba.taken_date DESC, ba.album_no DESC
LIMIT #{size} OFFSET #{skip}

mapper.delete:
DELETE FROM tbl_baby_album
WHERE album_no = #{albumNo}
AND baby_no IN (SELECT baby_no FROM tbl_baby_info WHERE email = #{email})

mapper.select:
SELECT COUNT(*)
FROM tbl_baby_album
WHERE album_no = #{albumNo} AND baby_no = #{babyNo}
